Visualisation of Posterior Variance Under Input Scaling
Using 
k(x,y) = \exp\!\biggl(-\frac{\|x-y\|^2}{2\ell^2}\biggr)



Code
n = 20

X = {
  function mulberry32(a) {
    return function() {
      a |= 0; a = a + 0x6D2B79F5 | 0;
      var t = Math.imul(a ^ a &gt;&gt;&gt; 15, 1 | a);
      t = t + Math.imul(t ^ t &gt;&gt;&gt; 7, 61 | t) ^ t;
      return ((t ^ t &gt;&gt;&gt; 14) &gt;&gt;&gt; 0) / 4294967296;
    }
  }
  const rng = mulberry32(42);
  return Array.from({length: n}, (_, i) =&gt; {
    const t = (2 * Math.PI * i) / n;
    return [1.2 * Math.cos(t) + 0.25 * (rng() - 0.5),
            1.2 * Math.sin(t) + 0.25 * (rng() - 0.5)];
  });
}

ell = 0.7
sigmaF2 = 1.0
lambda = 1e-3

// Inject styles to fix slider accent and plot text on dark Reveal background
themeStyle = html`&lt;style&gt;
  .ojs-cell input[type="range"],
  .reveal input[type="range"] {
    accent-color: var(--accent, #ee4558);
  }
  .ojs-cell input[type="number"],
  .reveal input[type="number"] {
    background: rgba(255,255,255,0.08);
    color: rgba(255,255,255,0.9);
    border: 1px solid rgba(255,255,255,0.2);
    border-radius: 4px;
  }
  .ojs-cell label, .ojs-cell output,
  .reveal form label, .reveal form output {
    color: rgba(255,255,255,0.85) !important;
  }
  .reveal .ojs-cell {
    display: flex;
    flex-direction: column;
    align-items: center;
  }
&lt;/style&gt;`

viewof r = Inputs.range([0, 2], {step: 0.01, value: 1.0, label: "scale r"})





















































Code
function k(x, y) {
  const dx = x[0] - y[0], dy = x[1] - y[1];
  return sigmaF2 * Math.exp(-(dx*dx + dy*dy) / (2 * ell * ell));
}

function gram(XA, XB) {
  const nA = XA.length, nB = XB.length;
  const K = Array.from({length: nA}, () =&gt; Array(nB).fill(0));
  for (let i = 0; i &lt; nA; i++)
    for (let j = 0; j &lt; nB; j++)
      K[i][j] = k(XA[i], XB[j]);
  return K;
}

function cholesky(A) {
  const m = A.length;
  const L = Array.from({length: m}, () =&gt; Array(m).fill(0));
  for (let i = 0; i &lt; m; i++) {
    for (let j = 0; j &lt;= i; j++) {
      let s = A[i][j];
      for (let p = 0; p &lt; j; p++) s -= L[i][p] * L[j][p];
      L[i][j] = (i === j) ? Math.sqrt(Math.max(s, 1e-14)) : s / L[j][j];
    }
  }
  return L;
}

function cholSolve(A, b) {
  const L = cholesky(A), m = A.length;
  const z = Array(m).fill(0);
  for (let i = 0; i &lt; m; i++) {
    let s = b[i];
    for (let p = 0; p &lt; i; p++) s -= L[i][p] * z[p];
    z[i] = s / L[i][i];
  }
  const x = Array(m).fill(0);
  for (let i = m - 1; i &gt;= 0; i--) {
    let s = z[i];
    for (let p = i + 1; p &lt; m; p++) s -= L[p][i] * x[p];
    x[i] = s / L[i][i];
  }
  return x;
}
































Code
origin = [0, 0]
rX = X.map(([x1, x2]) =&gt; [r * x1, r * x2])

posteriorResult = {
  const Krr = gram(rX, rX);
  for (let i = 0; i &lt; n; i++) Krr[i][i] += lambda;
  const a = rX.map(xi =&gt; k(xi, origin));
  const u = cholSolve(Krr, a);
  const g = a.reduce((acc, ai, i) =&gt; acc + ai * u[i], 0);
  return {g, sigma2: k(origin, origin) - g};
}

























Code
axisLim = 3

// Dark-theme-friendly plot style string
darkStyle = "background:transparent; color:rgba(255,255,255,0.82); font-size:13px;"

curve = {
  function sigma2At(rv) {
    const sX = X.map(([x1, x2]) =&gt; [rv * x1, rv * x2]);
    const A = gram(sX, sX);
    for (let i = 0; i &lt; n; i++) A[i][i] += lambda;
    const av = sX.map(xi =&gt; k(xi, origin));
    const uv = cholSolve(A, av);
    const gv = av.reduce((acc, ai, i) =&gt; acc + ai * uv[i], 0);
    return k(origin, origin) - gv;
  }
  return Array.from({length: 201}, (_, i) =&gt; {
    const rv = i * (2 / 200);
    return {r: rv, sigma2: sigma2At(rv)};
  });
}

leftPlot = Plot.plot({
  width: 380,
  height: 340,
  style: darkStyle,
  x: {label: "x₁", domain: [-axisLim, axisLim]},
  y: {label: "x₂", domain: [-axisLim, axisLim]},
  marks: [
    Plot.dot(rX, {
      x: d =&gt; d[0], y: d =&gt; d[1],
      fill: "#93c5fd", r: 4, opacity: 0.9
    }),
    Plot.dot([[0, 0]], {
      x: d =&gt; d[0], y: d =&gt; d[1],
      stroke: "#ee4558", fill: "none",
      strokeWidth: 2.5, r: 7, symbol: "cross"
    })
  ]
})

rightPlot = Plot.plot({
  width: 380,
  height: 340,
  style: darkStyle,
  x: {label: "scale r", domain: [0, 2]},
  y: {label: "σ²(0; rX)", domain: [0, sigmaF2 * 1.05]},
  marks: [
    Plot.ruleY([0], {stroke: "rgba(255,255,255,0.15)"}),
    Plot.line(curve, {x: "r", y: "sigma2", stroke: "#93c5fd", strokeWidth: 2}),
    Plot.dot([{r: +r, sigma2: posteriorResult.sigma2}], {
      x: "r", y: "sigma2", r: 6, fill: "#ee4558"
    })
  ]
})

html`&lt;div style="display:flex; gap:24px; align-items:flex-start; flex-wrap:wrap; justify-content:center;"&gt;
  &lt;div style="text-align:center;"&gt;
    &lt;div style="font-weight:600; margin-bottom:6px; color:rgba(255,255,255,0.85);"&gt;
      Scaled locations &lt;i&gt;r&lt;/i&gt;&lt;b&gt;X&lt;/b&gt; in ℝ²
    &lt;/div&gt;
    ${leftPlot}
  &lt;/div&gt;
  &lt;div style="text-align:center;"&gt;
    &lt;div style="font-weight:600; margin-bottom:6px; color:rgba(255,255,255,0.85);"&gt;
      Posterior variance at the origin
    &lt;/div&gt;
    ${rightPlot}
  &lt;/div&gt;
&lt;/div&gt;`

