function k_ee(x, y) {
  const dx = x[0] - y[0], dy = x[1] - y[1];
  const dist2 = dx*dx + dy*dy;
  return Math.exp(-(1 - Math.exp(-dist2)));
}

function gram_ee(XA, XB) {
  const nA = XA.length, nB = XB.length;
  const K = Array.from({length: nA}, () =&gt; Array(nB).fill(0));
  for (let i = 0; i &lt; nA; i++)
    for (let j = 0; j &lt; nB; j++)
      K[i][j] = k_ee(XA[i], XB[j]);
  return K;
}

function cholesky_ee(A) {
  const m = A.length;
  const L = Array.from({length: m}, () =&gt; Array(m).fill(0));
  for (let i = 0; i &lt; m; i++) {
    for (let j = 0; j &lt;= i; j++) {
      let s = A[i][j];
      for (let p = 0; p &lt; j; p++) s -= L[i][p] * L[j][p];
      L[i][j] = (i === j) ? Math.sqrt(Math.max(s, 1e-14)) : s / L[j][j];
    }
  }
  return L;
}

function cholSolve_ee(A, b) {
  const L = cholesky_ee(A), m = A.length;
  const z = Array(m).fill(0);
  for (let i = 0; i &lt; m; i++) {
    let s = b[i];
    for (let p = 0; p &lt; i; p++) s -= L[i][p] * z[p];
    z[i] = s / L[i][i];
  }
  const x = Array(m).fill(0);
  for (let i = m - 1; i &gt;= 0; i--) {
    let s = z[i];
    for (let p = i + 1; p &lt; m; p++) s -= L[p][i] * x[p];
    x[i] = s / L[i][i];
  }
  return x;
}
































